package ru.nartov.lab6.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import ru.nartov.lab6.dao.SubjectDAO;import ru.nartov.lab6.dto.SubjectRequest;import ru.nartov.lab6.entity.Subject;import ru.nartov.lab6.exception.ResourceNotFoundException;import java.util.List;
@Service @Transactional public class SubjectServiceImpl implements SubjectService{private final SubjectDAO dao;public SubjectServiceImpl(SubjectDAO d){dao=d;}@Transactional(readOnly=true)public List<Subject> findAll(){return dao.findAll();}@Transactional(readOnly=true)public Subject findById(Long id){return dao.findById(id).orElseThrow(()->new ResourceNotFoundException("Дисциплина с id="+id+" не найдена."));}public Subject create(SubjectRequest r){return dao.save(new Subject(r.getName(),r.getHours(),r.getSemester()));}public Subject update(Long id,SubjectRequest r){Subject s=findById(id);s.setName(r.getName());s.setHours(r.getHours());s.setSemester(r.getSemester());return dao.save(s);}public void delete(Long id){dao.delete(findById(id));}}
